<script setup lang="ts">
import {qualityText as qt} from '../i18n'

import {reactive} from 'vue'
import type {QualityClient} from '../client'
import type {CheckRecord} from '../types'
import {useQualityRepair} from '../useQualityRepair'
const props=defineProps<{api:QualityClient}>(),emit=defineEmits<{changed:[]}>(),vm=reactive(useQualityRepair(props.api,async()=>emit('changed')))
defineExpose({show:(record:CheckRecord)=>vm.show(record)})
</script>
<template><a-modal v-model:open="vm.open" :title="vm.linked?qt('linkedRepairOrder'):qt('createRepairFromIssue')" :footer="null" width="620"><a-alert v-if="vm.error" :message="vm.error" type="error" show-icon /><a-spin :spinning="vm.loading"><a-descriptions v-if="vm.linked" :column="1" bordered><a-descriptions-item :label="qt('repairNumber')">{{vm.linked.number}}</a-descriptions-item><a-descriptions-item :label="qt('orderStatus')">{{[qt('pendingAssignment'),qt('inProgress'),qt('finished'),qt('obsolete'),qt('closed'),qt('archived'),qt('pendingAcceptance'),qt('pendingFollowUp'),qt('pendingFollowUpVisit'),qt('pendingApproval')][vm.linked.status]}}</a-descriptions-item><a-descriptions-item :label="qt('orderId')">{{vm.linked.id}}</a-descriptions-item></a-descriptions><a-form v-else layout="vertical" :model="vm.form" @finish="vm.submit">
 <a-form-item :label="qt('repairCategory')" name="categoryId" :rules="[{required:true,message:qt('selectARepairCategory')}]"><a-select v-model:value="vm.form.categoryId" :options="vm.choices('category')" /></a-form-item><a-form-item :label="qt('repairChannel')" name="channelId" :rules="[{required:true,message:qt('selectARepairChannel')}]"><a-select v-model:value="vm.form.channelId" :options="vm.choices('channel')" /></a-form-item><a-form-item :label="qt('issueLabels')"><a-select v-model:value="vm.form.labelIds" mode="multiple" :options="vm.choices('label')" /></a-form-item><a-form-item :label="qt('issueDescription')" name="description" :rules="[{required:true,message:qt('enterAnIssueDescription')}]"><a-textarea v-model:value="vm.form.description" :rows="4" :maxlength="800" /></a-form-item><a-form-item :label="qt('contact')" name="contactName" :rules="[{required:true,message:qt('enterTheContactName')}]"><a-input v-model:value="vm.form.contactName" /></a-form-item><a-form-item :label="qt('phone')" name="contactPhone" :rules="[{required:true,message:qt('enterAContactPhoneNumber')}]"><a-input v-model:value="vm.form.contactPhone" /></a-form-item><a-form-item :label="qt('issueLocation')"><a-radio-group v-model:value="vm.form.positionType"><a-radio :value="1">{{qt('publicArea')}}</a-radio><a-radio :value="2">{{qt('indoor')}}</a-radio></a-radio-group></a-form-item><a-form-item :label="qt('locationDetails')"><a-input v-model:value="vm.form.location" /></a-form-item><a-form-item :label="qt('urgency')"><a-select v-model:value="vm.form.urgency" :options="[{value:1,label:qt('normal')},{value:2,label:qt('urgent')},{value:3,label:qt('critical')}]" /></a-form-item><p>{{qt('theInspectionProjectAndSitePhotosWillBeIncluded')}}</p><a-button type="primary" html-type="submit" :loading="vm.loading">{{qt('createRepairOrder')}}</a-button></a-form></a-spin></a-modal></template>
